import textwrap
code = textwrap.dedent('''
import argparse
import csv
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP
import json

def parse_ts(ts_str):
    ts_str = ts_str.strip()
    if ts_str.endswith('Z'):
        ts_str = ts_str[:-1] + '+00:00'
    return datetime.fromisoformat(ts_str)

def reconcile(csv_path):
    records = {}
    with open(csv_path, mode='r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            tx_id = row['tx_id']
            ts = parse_ts(row['timestamp'])
            if tx_id not in records or ts >= records[tx_id]['ts']:
                records[tx_id] = {'ts': ts, 'amount': Decimal(row['amount'].strip()), 'status': row['status'].strip()}
    total_valid_amount = Decimal('0')
    valid_count = 0
    failed_count = 0
    for rec in records.values():
        if rec['status'] == 'VALID':
            total_valid_amount += rec['amount']
            valid_count += 1
        elif rec['status'] == 'FAILED':
            failed_count += 1
    rounded_total = total_valid_amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return {'total_valid_amount': float(rounded_total), 'valid_count': valid_count, 'failed_count': failed_count}

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--input', required=True)
    args = parser.parse_args()
    result = reconcile(args.input)
    print(json.dumps(result))

if __name__ == '__main__':
    main()
''').lstrip()
